using System.Reflection;
using EvoSim.Core;

namespace EvoSim.Observer;

// One entry per exposed model field. These describe the current rules, not promised behavior.
internal static class SettingHelp
{
 internal static readonly IReadOnlyDictionary<string,string> Descriptions = new Dictionary<string,string>
 {
  ["MapSize"]="Karenin bir kenarındaki dünya birimi sayısı: 128, 192 veya 256. 256 haritanın alanı 128'in dört katıdır. Canlı/ağaç/çayır sayıları kendiliğinden artmaz; ayrı ayarlanır. Bedenler, hızlar ve görüş uzaklıkları aynı kalır. Büyük haritada ayrıntı için yakınlaşabilirsin. Referans profil değiştirmek seçtiğin harita boyutunu korur.",
  ["Herbivores"]="Dünya kurulurken doğacak otçul grubunun birey sayısı. Sonraki nüfus, gerçek doğum ve ölümlerle değişir.",
  ["Carnivores"]="Dünya kurulurken doğacak etçil grubunun birey sayısı. Sıfır seçersen dünya etçil kurucular olmadan başlar.",
  ["HerbBreedingMode"]="Otçul grubunda üreme biçimi: Kapalı doğumu engeller; Eşeyli iki uygun bireyin temasını ve karşılıklı ağ sinyalini ister; Eşeysiz tek bireyin sinyalini ve tüm yavru bedelini ödemesini ister. Eşeysiz yavru, nadir mutasyon dışında ebeveyn kopyasıdır.",
  ["CarnBreedingMode"]="Etçil grubunda üreme biçimi. Kapalı, Eşeyli veya Eşeysiz seçebilirsin. Eşeylide bedeli iki ebeveyn paylaşır, eşeysizde tek ebeveyn öder. Diğer yaş, enerji, sağlık ve bekleme koşulları sürer.",
  ["HerbReproductiveDrive"]="Otçul grubunun üreme hazır olma sinyalini 2 × bu değer ile ölçekler. 0.5 referanstır; 0 içsel sinyali susturur, 1 iki katına çıkarır. Ağın üreme kararını veya doğum sayısını garanti etmez. Doğumu tamamen kapatmak için üreme biçimini Kapalı seç. Şimdilik dünya kuralıdır, kalıtsal gen değildir.",
  ["CarnReproductiveDrive"]="Etçil grubunun üreme hazır olma girdisinin gücü. 0.5 referanstır. Ağ bu sinyali nasıl kullanacağını kalıtsal ağırlıklarıyla belirler; yüksek değer doğrudan daha çok doğum anlamına gelmez. Doğumu tamamen kapatma ayarı üreme biçimidir.",
  ["BreedContactRange"]="Eşeyli üreme temasında beden yarıçaplarına eklenen mesafe; dünya birimi. Yön bulma veya eşe gitme komutu eklemez. Görüş hattı ve mevcut iki birim yakınlık sınırı ayrıca uygulanır.",
  ["TreeRadiusMin"]="Ağaç tacının en küçük yarıçapı; dünya birimi. Gövde engeli aynı kalır. Meyveler taç yarıçapının belirlenen oranında büyüdüğü için gerçek besin konumları da değişir.",
  ["TreeRadiusMax"]="Ağaç tacının en büyük yarıçapı. Alt sınır ile bu sınır arasından rastgele seçilir. Geniş taçlar altındaki canlılar için otomatik saydamlık çalışır; ağaç gövdesini büyütmez.",
  ["TreeSpacing"]="Ağaç merkezleri arasındaki en az mesafe. Büyük değer daha seyrek koruluklar oluşturur; uygun yer kalmazsa istenen ağaç sayısının tamamı yerleşmeyebilir.",
  ["TreeMoistureAffinity"]="Ağaç yerleşim denemesinin kabul ihtimali, yerel nem ile bu katsayının çarpımıdır. Nemli yerler daha elverişlidir. 0 ağaç yerleşimini kapatır; 1 her araziye ağaç garantisi vermez.",
  ["TreeFruitRadius"]="Meyvelerin merkezden uzaklığı, taç yarıçapının bu oranıdır. 0 merkeze toplar, 1 taç kenarına taşır. Gövdeye çok yakın veya su/engelin üzerindeki meyvelere bazı canlılar ulaşamayabilir.",
  ["FruitDroughtTolerance"]="Kuraklıkta meyve yenilenme hızının korunan payı. Sayaç hızı bu değer + (1 − bu değer) × su seviyesidir. 1 kuraklığın meyve süresini etkilemesini kapatır; çayır ve canlıların su dengesi ayrıca etkilenir.",
  ["TreeCount"]="Haritaya yerleştirilmeye çalışılan meyve ağacı sayısı. Ağaçlar uygun karada, su ve diğer engellere mesafe bırakılarak rastgele yerleşir.",
  ["RockClusters"]="Geçişi ve görüşü etkileyen kaya gruplarının başlangıç sayısı. Kayalar henüz toplanabilen inşaat malzemesi değildir.",
