 };
 internal static string For(string key)=>Descriptions.TryGetValue(key,out var text)?text+(WorldCalendar.UsesYears(key)?" Yaş ve ömür değerlerini yıl olarak gir. 365 gün = 1 yıl; eski 1 simülasyon saniyesi = 1 dünya günü.":""):"Bu sayısal değer yeni dünyanın kurallarına kaydedilir. Ayrıntılı model açıklaması bu sürümde henüz eklenmemiştir.";
 internal static string[] MissingFields()=>typeof(WorldConfig).GetFields().Where(f=>f.GetCustomAttribute<SettingAttribute>()!=null&&!Descriptions.ContainsKey(f.Name)).Select(f=>f.Name).ToArray();
}
